motion:
/* hook: the pool of torchlight breathes on the floor; "sealed" lands on the word */
tl.to("#poolhe", { attr: { rx: 232 }, duration: 1.4, yoyo: true, repeat: 5, ease: "sine.inOut" }, 2.7);
tl.fromTo("#sealedb", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 9.45);
/* wide: you walk the length of the train, engine to lever */
tl.fromTo("#walker", { x: 0 }, { x: 920, duration: 4.3, ease: "none" }, 12.5);
/* rule 1 obeyed: the beam sweeps the floor, never lifts; EMPTY on the word */
tl.fromTo("#poolae", { attr: { cx: 470 } }, { attr: { cx: 610 }, duration: 1.5, yoyo: true, repeat: 1, ease: "sine.inOut" }, 22.3);
tl.fromTo("#empty1", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, 24.9);
/* the plant: the radio's instruction, on "do not open" */
tl.fromTo("#noopen", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 29.45);
/* rule 2 obeyed: the count on the spoken numbers */
[[38.40, "12"], [38.92, "20"], [39.42, "26"]].forEach(([t, v]) => tl.set("#cnum", { textContent: v }, t));
tl.fromTo("#empty2", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, 40.2);
/* the count: carriages 12-31 light as they are claimed, the counter climbing with them */
for (let n = 12; n <= 31; n++) {
  const t = 42.3 + (n - 12) * 0.095;
  tl.fromTo(`#c${n}`, { opacity: 0.25 }, { opacity: 1, duration: 0.12 }, t);
  tl.set("#cn", { textContent: String(n) }, t);
}
/* rule 3 obeyed: you reach for the lever, not the door */
tl.fromTo("#noneed", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 54.9);
/* 4:31: the knocking. The door moves on each knock; the pattern writes itself in bars */
tl.set("#knockword", { textContent: "" }, 57.2);
tl.to("#knockword", { opacity: 1, duration: 0.9, scrambleText: { text: "KNOCKING", chars: "upperCase", speed: 0.7 } }, 59.7);
const KN = [63.50, 63.75, 64.00, 64.15, 64.30, 64.45, 64.77, 65.00, 65.23];
KN.forEach((t, i) => {
  tl.to(`#knocks .kb:nth-child(${i + 1})`, { opacity: 1, duration: 0.06 }, t);
  tl.to("#door", { x: i < 3 || i > 5 ? 7 : 4, duration: 0.05, yoyo: true, repeat: 1, ease: "none" }, t);
});
tl.to("#door", { x: 5, duration: 0.05, yoyo: true, repeat: 5, ease: "none" }, 59.8);
/* the recall: the same pattern, in the mirror, in amber; then the lights go out — a cut, not a fade */
tl.to(".mb", { opacity: 1, duration: 0.08, stagger: 0.07, ease: "none" }, 67.45);
tl.to("#mirrorlight", { opacity: 0, duration: 0.18, ease: "none" }, 73.55);
tl.fromTo("#lightsout", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, 73.7);
/* three days on foot, down the same line you took */
tl.fromTo("#her", { y: 0 }, { y: 700, duration: 4.8, ease: "none" }, 75.3);
tl.fromTo("#following", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, 77.2);
/* the twist: the door, and what it was sealed against */
tl.to("#door", { x: 4, duration: 0.05, yoyo: true, repeat: 3, ease: "none" }, 81.2);
tl.fromTo("#against", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 84.95);
